<style>
*{box-sizing:border-box}html,body{margin:0;height:100%;font-family:"Segoe UI",system-ui,sans-serif;background:#182131;color:#fff}.app{height:100%;display:grid;grid-template-rows:58px 1fr 26px}.top{display:flex;align-items:center;gap:10px;padding:8px 12px;background:#101827}.top h1{margin:0;font-size:18px;color:#ffd54a;white-space:nowrap}.score{border-radius:999px;padding:7px 13px;font-weight:800}.blue{background:#1d4ed8}.red{background:#b91c1c}.timer{margin:auto;background:#080d18;border-radius:14px;padding:6px 16px;font-size:22px;font-weight:900}.btn{border:0;border-radius:10px;padding:8px 11px;font-weight:700;cursor:pointer;background:#334155;color:#fff}.btn.primary{background:#f59e0b;color:#111}.btn.danger{background:#dc2626}.btn.light{background:#e2e8f0;color:#172033}.setup{padding:18px;overflow:auto}.setup .box{max-width:1100px;margin:auto;background:#0f172a;border-radius:18px;padding:18px}.row{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}label{font-size:13px;opacity:.84}input,select,textarea{width:100%;border:0;border-radius:9px;padding:9px;margin:4px 0 10px;font:inherit}.bankbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:13px 0 8px}.bankbar select{width:min(350px,100%);margin:0}.bankbar .status{font-size:13px;color:#cbd5e1}.question-list{display:grid;gap:10px}.question-card{background:#17243a;border:1px solid #334155;border-radius:13px;padding:12px}.question-head{display:flex;justify-content:space-between;align-items:center;gap:8px}.question-head strong{color:#fde68a}.question-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 9px}.question-grid .prompt{grid-column:1/-1}.question-card input{margin-bottom:7px}.question-actions{display:flex;gap:6px}.small{padding:5px 8px;font-size:12px}.empty{padding:20px;text-align:center;color:#94a3b8;border:1px dashed #475569;border-radius:12px}.import-area{min-height:170px;font-family:ui-monospace,monospace}.play{display:grid;grid-template-columns:1fr minmax(300px,42vw) 1fr;gap:10px;padding:10px;min-height:0}.panel{border-radius:18px;padding:14px;display:grid;grid-template-rows:1fr auto;min-height:0}.panel.b{background:#1d4ed8}.panel.r{background:#b91c1c}.q{font-size:clamp(16px,2.1vw,28px);font-weight:800;text-align:center;display:grid;place-items:center;padding:8px}.opts{display:grid;grid-template-columns:1fr 1fr;gap:10px}.opts button{min-height:78px;border:0;border-radius:16px;background:#fff;color:#111;font-weight:800;font-size:clamp(15px,1.7vw,22px);cursor:pointer}.opts button.ok{background:#86efac}.opts button.bad{background:#fecaca}.mid{background:linear-gradient(#bfe7ff,#f4f6fb 65%);border-radius:18px;overflow:hidden;position:relative}.field{height:100%;min-height:300px;position:relative;background:linear-gradient(transparent 70%,#63a83d 70%,#43852f)}.line{position:absolute;left:50%;top:8%;bottom:8%;border-left:3px dashed #fff;transform:translateX(-50%)}.ropebox{position:absolute;left:50%;top:50%;width:93%;height:205px;transform:translate(-50%,-50%);transition:transform .48s cubic-bezier(.15,.9,.25,1)}.rope{position:absolute;top:107px;left:3%;width:94%;height:12px;border-radius:9px;background:repeating-linear-gradient(45deg,#603b21 0 7px,#a66b37 7px 14px);box-shadow:0 5px 4px #0004}.flag{position:absolute;left:50%;top:91px;width:12px;height:40px;background:#ef4444;transform:translateX(-50%);box-shadow:0 2px 3px #0004}.team{position:absolute;top:43px;display:flex;gap:4px}.team.blue-team{left:5%}.team.red-team{right:5%;transform:scaleX(-1)}.puller{width:44px;height:115px;position:relative;transform-origin:bottom center}.puller:before{content:"";position:absolute;top:0;left:10px;width:25px;height:25px;border-radius:50%;background:radial-gradient(circle at 35% 35%,#ffe1bc 0 20%,#c88761 72%);box-shadow:0 2px 1px #0003}.puller:after{content:"";position:absolute;top:25px;left:7px;width:31px;height:54px;border-radius:13px 13px 8px 8px;background:linear-gradient(100deg,#64a9ff,#174ea6);box-shadow:inset -6px 0 #0003,0 4px 3px #0003}.red-team .puller:after{background:linear-gradient(100deg,#ff7373,#a31323)}.arm{position:absolute;top:39px;left:28px;width:36px;height:9px;background:#e5ae82;border-radius:8px;transform:rotate(18deg);z-index:2}.leg{position:absolute;top:75px;width:12px;height:39px;background:#1f2937;border-radius:7px;transform:rotate(15deg);left:11px}.leg.two{left:25px;transform:rotate(-13deg)}.pulling .puller{animation:pull .48s ease-out 2}.pulling .rope{animation:rope-tug .48s ease-out 2}@keyframes pull{50%{transform:translateX(-9px) rotate(-9deg)}}@keyframes rope-tug{50%{filter:brightness(1.35);transform:scaleY(1.25)}}.credit{display:flex;align-items:center;justify-content:center;font-size:11px;opacity:.7;background:#0005}.overlay{position:fixed;inset:0;display:none;place-items:center;background:#0009;z-index:9}.overlay.show{display:grid}.modal{background:#fff;color:#111;border-radius:18px;padding:22px;min-width:min(600px,92vw);max-width:760px;max-height:90vh;overflow:auto}.modal h2{margin-top:0}.modal-actions{display:flex;gap:8px;justify-content:flex-end}.modal[hidden]{display:none}@media(max-width:780px){.app{grid-template-rows:auto 1fr 26px}.top{flex-wrap:wrap}.timer{margin:0}.row,.question-grid,.play{grid-template-columns:1fr}.play{overflow:auto}.mid{min-height:250px}.top h1{width:100%}}
</style>
</head><body>
<div class="app"><div class="top"><h1>Kéo Co Kiến Thức</h1><div class="score blue" id="sBlue">Đội Xanh 0</div><div class="timer" id="timer">03:00</div><div class="score red" id="sRed">0 Đội Đỏ</div><button class="btn" id="muteBtn" type="button">Tắt âm</button><button class="btn" id="fullBtn" type="button">Toàn màn hình</button><button class="btn" id="exitBtn" type="button">Thoát</button></div>
<main class="setup" id="setup"><div class="box"><h2 style="margin-top:0">Tạo trận kéo co</h2><div class="row"><div><label>Đội xanh</label><input id="nBlue" value="Đội Xanh"></div><div><label>Đội đỏ</label><input id="nRed" value="Đội Đỏ"></div><div><label>Thời gian (phút)</label><input id="mins" type="number" min="1" value="3"></div></div><div class="row"><div><label>Cách chơi</label><select id="mode"><option value="split">Mỗi đội một câu riêng</option><option value="shared">Hai đội chung một câu</option></select></div><div><label>Cách biệt để thắng</label><input id="winBy" type="number" min="2" value="5"></div><div><label>Hiện lại câu đã dùng</label><select id="loopQ"><option value="1">Có</option><option value="0">Không</option></select></div></div>
<section><h3>Ngân hàng câu hỏi</h3><div class="bankbar"><select id="setList"><option value="">Bộ câu hỏi mới (chưa lưu)</option></select><button class="btn light" id="loadBtn" type="button">Tải bộ đã chọn</button><button class="btn light" id="newBtn" type="button">Tạo bộ mới</button><button class="btn light" id="importBtn" type="button">Nhập định dạng cũ</button><span class="status" id="bankStatus"></span></div><div class="row"><div style="grid-column:span 2"><label>Tên bộ câu hỏi</label><input id="setTitle" placeholder="Ví dụ: Ôn tập Toán lớp 5"></div><div><label><input id="setShared" type="checkbox" style="width:auto;margin-right:6px">Cho phép mọi người dùng</label><small style="display:block;color:#94a3b8">Quản trị viên luôn xem và quản lý mọi bộ.</small></div></div><div class="bankbar"><button class="btn" id="addQuestion" type="button">+ Thêm câu hỏi</button><button class="btn primary" id="saveBtn" type="button">Lưu ngân hàng</button><button class="btn danger" id="deleteBtn" type="button" hidden>Xóa bộ này</button></div><div class="question-list" id="questionList"></div></section><button class="btn primary" id="startBtn" type="button">Bắt đầu thi đấu</button></div></main>
<div class="play" id="play" hidden><section class="panel b"><div class="q" id="qBlue"></div><div class="opts" id="oBlue"></div></section><section class="mid"><div class="field"><div class="line"></div><div class="ropebox" id="rope"><div class="rope"></div><div class="flag"></div><div class="team blue-team"><div class="puller"><i class="arm"></i><i class="leg"></i><i class="leg two"></i></div><div class="puller"><i class="arm"></i><i class="leg"></i><i class="leg two"></i></div><div class="puller"><i class="arm"></i><i class="leg"></i><i class="leg two"></i></div></div><div class="team red-team"><div class="puller"><i class="arm"></i><i class="leg"></i><i class="leg two"></i></div><div class="puller"><i class="arm"></i><i class="leg"></i><i class="leg two"></i></div><div class="puller"><i class="arm"></i><i class="leg"></i><i class="leg two"></i></div></div></div></div></section><section class="panel r"><div class="q" id="qRed"></div><div class="opts" id="oRed"></div></section></div><div class="credit">Hệ Sinh Thái Quản lý Nhà Trường - Thiết kế bởi thầy giáo Nguyễn Hồng Dân -</div></div>
<div class="overlay" id="overlay"><div class="modal"><h2 id="winTitle">Kết thúc</h2><p id="winText"></p><button class="btn" id="again" type="button">Chơi lại</button></div></div><div class="overlay" id="importOverlay"><div class="modal"><h2>Nhập ngân hàng định dạng cũ</h2><p>Dán mỗi dòng theo mẫu: <code>Câu hỏi | A | B | C | D | đáp án 1-4</code>.</p><textarea class="import-area" id="importText"></textarea><div class="modal-actions"><button class="btn light" id="cancelImport" type="button">Hủy</button><button class="btn primary" id="confirmImport" type="button">Nhập câu hỏi</button></div></div></div>
<script>
const API='<?= e($base) ?>hoclieu_game_keoco_api.php', CSRF='<?= e($_SESSION['keoco_question_bank_csrf']) ?>';
const DEFAULT=`Thủ đô của Việt Nam là thành phố nào? | Hà Nội | Huế | TP. Hồ Chí Minh | Đà Nẵng | 1
Sông nào dài nhất Việt Nam? | Hồng | Mekong | Đà | Đồng Nai | 2
Phương trình 2x + 6 = 0 có nghiệm là? | x = 6 | x = 3 | x = -3 | x = -6 | 3
1 giờ có bao nhiêu phút? | 30 | 60 | 90 | 100 | 2
Hình nào có 3 cạnh? | Vuông | Tròn | Tam giác | Chữ nhật | 3
Năm 1945 gắn với sự kiện nào? | Đổi mới | Cách mạng tháng Tám | Điện Biên Phủ | Thống nhất | 2
Kết quả 7 x 8 là? | 54 | 56 | 64 | 48 | 2
Hành tinh chúng ta đang sống tên gì? | Sao Hỏa | Mặt Trăng | Trái Đất | Sao Kim | 3`;
let currentSetId=null, canEdit=true, bank=[],blue=0,red=0,tLeft=180,tick=null,mute=false,mode='split',winBy=5,loopQ=true,usedB=[],usedR=[],curB=null,curR=null,lockB=false,lockR=false,names={blue:'Đội Xanh',red:'Đội Đỏ'},audioCtx=null;
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function parseBank(text){return text.split(/\n+/).map(line=>{const p=line.split('|').map(s=>s.trim());return p.length>=6&&p[0]&&p.slice(1,5).every(Boolean)?{question_text:p[0],option_a:p[1],option_b:p[2],option_c:p[3],option_d:p[4],correct_option:Math.max(1,Math.min(4,parseInt(p[5],10)||1))}:null}).filter(Boolean)}
function card(q={question_text:'',option_a:'',option_b:'',option_c:'',option_d:'',correct_option:1}){const el=document.createElement('article');el.className='question-card';el.innerHTML=`<div class="question-head"><strong>Câu hỏi</strong><div class="question-actions"><button type="button" class="btn light small duplicate">Nhân bản</button><button type="button" class="btn danger small remove">Xóa</button></div></div><div class="question-grid"><label class="prompt">Nội dung<input class="question_text" value="${esc(q.question_text)}"></label><label>A<input class="option_a" value="${esc(q.option_a)}"></label><label>B<input class="option_b" value="${esc(q.option_b)}"></label><label>C<input class="option_c" value="${esc(q.option_c)}"></label><label>D<input class="option_d" value="${esc(q.option_d)}"></label><label>Đáp án đúng<select class="correct_option"><option value="1">A</option><option value="2">B</option><option value="3">C</option><option value="4">D</option></select></label></div>`;el.querySelector('.correct_option').value=q.correct_option||1;el.querySelector('.remove').onclick=()=>{el.remove();updateEmpty()};el.querySelector('.duplicate').onclick=()=>{const copy=readCard(el);el.after(card(copy));updateEmpty()};return el}
function renderQuestions(rows){$('questionList').innerHTML='';rows.forEach(q=>$('questionList').append(card(q)));updateEmpty()}
function updateEmpty(){$('questionList').querySelector('.empty')?.remove();if(!$('questionList').children.length){const e=document.createElement('div');e.className='empty';e.textContent='Chưa có câu hỏi. Hãy thêm câu hỏi hoặc nhập định dạng cũ.';$('questionList').append(e)}}
function readCard(el){let q={};['question_text','option_a','option_b','option_c','option_d','correct_option'].forEach(k=>q[k]=el.querySelector('.'+k).value.trim());q.correct_option=Number(q.correct_option);return q}
function questionRows(){return [...$('questionList').querySelectorAll('.question-card')].map(readCard)}
function editorState(edit){['setTitle','setShared','addQuestion','saveBtn','importBtn'].forEach(id=>$(id).disabled=!edit);$('questionList').querySelectorAll('input,select,button').forEach(el=>el.disabled=!edit)}
async function request(action,data={},method='POST'){const o=method==='GET'?{headers:{Accept:'application/json'}}:{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({action,csrf:CSRF,...data})};const res=await fetch(method==='GET'?API+'?action='+encodeURIComponent(action)+(data.id?'&id='+encodeURIComponent(data.id):''):API,o);const json=await res.json().catch(()=>({}));if(!res.ok||!json.ok)throw Error(json.message||'Không thể xử lý yêu cầu.');return json}
function status(s){$('bankStatus').textContent=s}
async function refreshSets(){try{const d=await request('list',{},'GET'),selected=String(currentSetId||'');$('setList').innerHTML='<option value="">Bộ câu hỏi mới (chưa lưu)</option>'+d.sets.map(s=>`<option value="${s.id}">${esc(s.title)} (${s.question_count} câu)${s.is_shared?' · dùng chung':''}${s.can_edit?'':''}</option>`).join('');$('setList').value=selected;status(d.sets.length?'':'Chưa có bộ nào đã lưu.')}catch(e){status(e.message)}}
function resetSet(){currentSetId=null;canEdit=true;$('setList').value='';$('setTitle').value='';$('setShared').checked=false;$('deleteBtn').hidden=true;renderQuestions(parseBank(DEFAULT));editorState(true);status('Bộ câu hỏi mới')}
async function loadSet(){const id=$('setList').value;if(!id)return resetSet();try{const d=await request('get',{id},'GET');currentSetId=d.set.id;canEdit=d.set.can_edit;$('setTitle').value=d.set.title;$('setShared').checked=d.set.is_shared;$('deleteBtn').hidden=!canEdit;renderQuestions(d.questions);editorState(canEdit);status(canEdit?'Đã tải bộ câu hỏi.':'Bộ câu hỏi dùng chung (chỉ xem).')}catch(e){status(e.message)}}
$('addQuestion').onclick=()=>{$('questionList').querySelector('.empty')?.remove();$('questionList').append(card());};$('newBtn').onclick=resetSet;$('loadBtn').onclick=loadSet;$('setList').onchange=loadSet;
$('importBtn').onclick=()=>{$('importText').value='';$('importOverlay').classList.add('show')};$('cancelImport').onclick=()=>$('importOverlay').classList.remove('show');$('confirmImport').onclick=()=>{const rows=parseBank($('importText').value);if(!rows.length)return alert('Không tìm thấy dòng đúng định dạng.');renderQuestions(rows);$('importOverlay').classList.remove('show');status('Đã nhập '+rows.length+' câu hỏi; bấm Lưu ngân hàng để lưu lại.')};
$('saveBtn').onclick=async()=>{const title=$('setTitle').value.trim(),questions=questionRows();if(!title)return alert('Hãy nhập tên bộ câu hỏi.');if(!questions.length)return alert('Hãy thêm ít nhất một câu hỏi.');try{status('Đang lưu...');const d=await request('save',{id:currentSetId,title,is_shared:$('setShared').checked,questions});currentSetId=d.id;await refreshSets();$('setList').value=String(currentSetId);$('deleteBtn').hidden=false;status(d.message)}catch(e){status(e.message)}};
$('deleteBtn').onclick=async()=>{if(!currentSetId||!confirm('Xóa vĩnh viễn bộ câu hỏi này?'))return;try{await request('delete',{id:currentSetId});currentSetId=null;await refreshSets();resetSet()}catch(e){status(e.message)}};
function sound(ok){if(mute)return;if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='triangle';o.frequency.value=ok?660:180;g.gain.value=.08;o.connect(g);g.connect(audioCtx.destination);o.start();g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+.18);o.stop(audioCtx.currentTime+.2)}
function pick(side){const used=side==='b'?usedB:usedR;let pool=bank.map((_,i)=>i).filter(i=>!used.includes(i));if(!pool.length){if(!loopQ)return null;if(side==='b')usedB=[];else usedR=[];pool=bank.map((_,i)=>i)}const i=pool[Math.floor(Math.random()*pool.length)];if(side==='b')usedB.push(i);else usedR.push(i);return bank[i]}
function renderMath(el){if(window.renderMathInElement)renderMathInElement(el,{delimiters:[{left:'$',right:'$',display:false},{left:'\\(',right:'\\)',display:false}]})}
function drawSide(side,item){const q=$(side==='b'?'qBlue':'qRed'),box=$(side==='b'?'oBlue':'oRed');if(!item){q.textContent='Hết câu hỏi';box.innerHTML='';return}q.textContent=item.q;renderMath(q);box.innerHTML='';item.opts.forEach((opt,idx)=>{const b=document.createElement('button');b.textContent=opt;b.onclick=()=>answer(side,idx,item,b,box);box.append(b);renderMath(b)})}
function shiftRope(){const diff=blue-red;$('rope').style.transform='translate(calc(-50% + '+Math.max(-210,Math.min(210,diff*18))+'px),-50%)';$('sBlue').textContent=names.blue+' '+blue;$('sRed').textContent=red+' '+names.red;$('rope').classList.remove('pulling');void $('rope').offsetWidth;$('rope').classList.add('pulling');if(Math.abs(diff)>=winBy)endGame(diff>0?names.blue:names.red)}
function nextShared(){const item=pick('b');curB=curR=item;lockB=lockR=false;drawSide('b',item);drawSide('r',item)}
function answer(side,idx,item,btn,box){if((side==='b'&&lockB)||(side==='r'&&lockR)||!item)return;const ok=idx===item.ans;sound(ok);[...box.children].forEach((el,i)=>{el.disabled=true;if(i===item.ans)el.classList.add('ok')});if(!ok)btn.classList.add('bad');if(ok){if(side==='b')blue++;else red++}shiftRope();if($('overlay').classList.contains('show'))return;if(mode==='shared'){lockB=lockR=true;setTimeout(nextShared,700)}else if(side==='b'){lockB=true;setTimeout(()=>{curB=pick('b');lockB=false;drawSide('b',curB)},650)}else{lockR=true;setTimeout(()=>{curR=pick('r');lockR=false;drawSide('r',curR)},650)}}
function fmt(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}function endGame(w){clearInterval(tick);$('winTitle').textContent=w?w+' thắng!':'Hết giờ';$('winText').textContent=names.blue+' '+blue+' – '+red+' '+names.red;$('overlay').classList.add('show')}
function start(){const rows=questionRows();if(rows.length<4)return alert('Cần ít nhất 4 câu hỏi.');if(rows.some(q=>!q.question_text||!q.option_a||!q.option_b||!q.option_c||!q.option_d))return alert('Mỗi câu hỏi phải có nội dung và đủ 4 đáp án.');bank=rows.map(q=>({q:q.question_text,opts:[q.option_a,q.option_b,q.option_c,q.option_d],ans:q.correct_option-1}));names.blue=$('nBlue').value||'Đội Xanh';names.red=$('nRed').value||'Đội Đỏ';mode=$('mode').value;winBy=Math.max(2,Number($('winBy').value)||5);loopQ=$('loopQ').value==='1';blue=red=0;usedB=[];usedR=[];tLeft=Math.max(1,Number($('mins').value)||3)*60;$('setup').hidden=true;$('play').hidden=false;$('timer').textContent=fmt(tLeft);shiftRope();if(mode==='shared')nextShared();else{curB=pick('b');curR=pick('r');drawSide('b',curB);drawSide('r',curR)}clearInterval(tick);tick=setInterval(()=>{tLeft--;$('timer').textContent=fmt(Math.max(0,tLeft));if(tLeft<=0)endGame(blue===red?null:(blue>red?names.blue:names.red))},1000)}
$('startBtn').onclick=start;$('muteBtn').onclick=function(){mute=!mute;this.textContent=mute?'Bật âm':'Tắt âm'};$('fullBtn').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();$('exitBtn').onclick=()=>{clearInterval(tick);location.href='<?= e($base) ?>hoclieu.php?tab=games'};$('again').onclick=()=>{$('overlay').classList.remove('show');$('play').hidden=true;$('setup').hidden=false};renderQuestions(parseBank(DEFAULT));refreshSets();
</script></body></html>
